// ---- calibrate per vehicle -------------------------------------------------
const PACK_KWH     = 5.0;   // usable pack energy, for rangeKm
const FALLBACK_WHKM = 60;   // used until the energy meter has a real figure
const TEMP_WARN_C  = 45;
const TEMP_CRIT_C  = 55;
const VEHICLES     = {};    // firmware deviceId -> fleet id; empty = DEFAULT_ID
const DEFAULT_ID   = 'CMT-01';
// ---------------------------------------------------------------------------

const parts = String(msg.topic || '').split('/');
const dev   = parts[1] || 'unknown';
const kind  = parts[2];
const base  = 'cmt/' + (VEHICLES[dev] || DEFAULT_ID) + '/';
const ts    = new Date().toISOString();   // the broker has a clock, the ESP32 does not
const p     = msg.payload || {};

if (kind === 'status') {
    return [[{ topic: base + 'status', retain: true,
               payload: { online: p.state === 'online' } }]];
}
if (kind !== 'data') return null;

// The firmware only sends signals that CHANGED since its last batch, so hold a
// running picture per device or half the fields vanish from every message.
const key = 'cmt:' + dev;
const st  = flow.get(key) || { sig: {}, alert: null };
Object.assign(st.sig, p.sig || {});

const s   = st.sig;
const e   = p.energy || {};
const gps = p.gps || {};
const out = [];

const num = v => (typeof v === 'number' && isFinite(v)) ? v : undefined;
const put = (o, k, v) => { if (v !== undefined) o[k] = v; };

// --- telemetry -------------------------------------------------------------
const t = { ts };
put(t, 'lat',        num(gps.lat));            // absent until a GPS exists
put(t, 'lng',        num(gps.lng));
put(t, 'speedKph',   num(s.speed));
put(t, 'odometerKm', num(s.distance_total));
put(t, 'tripKm',     num(e.km));
put(t, 'motorTempC', num(s.mcu_temp));
out.push({ topic: base + 'telemetry', payload: t });

// --- battery ---------------------------------------------------------------
const b = { ts };
put(b, 'packVoltage', num(s.batt_voltage));
put(b, 'totalPct',    num(s.soc));

const volt = num(s.batt_voltage);
const kw   = num(e.kW) !== undefined ? num(e.kW) : num(s.power);
if (volt > 0 && kw !== undefined) b.packCurrentA = +(kw * 1000 / volt).toFixed(1);

const whkm = num(e.recent) > 0 ? e.recent
           : num(e.whPerKm) > 0 ? e.whPerKm
           : FALLBACK_WHKM;
if (b.totalPct !== undefined) {
    b.rangeKm = Math.round(PACK_KWH * 1000 * b.totalPct / 100 / whkm);
}
// no per-cell data on this bus; emit the pack as one cell so the shape holds
if (b.packVoltage !== undefined) {
    b.cells = [{ id: 1, voltage: b.packVoltage, tempC: num(s.batt_temp_1), pct: b.totalPct }];
}
out.push({ topic: base + 'battery', payload: b });

// --- alert (edge-triggered, not once per second) ---------------------------
const bt = num(s.batt_temp_1);
let al = null;
if (s.fault) {
    al = { type: 'fault', severity: 'critical', message: 'VCU fault flag set' };
} else if (bt !== undefined && bt >= TEMP_WARN_C) {
    al = { type: 'over_temp',
           severity: bt >= TEMP_CRIT_C ? 'critical' : 'warning',
           message: 'Pack at ' + bt.toFixed(1) + 'C' };
} else if (s.warning) {
    al = { type: 'warning', severity: 'warning', message: 'VCU warning flag set' };
}

const fingerprint = al ? al.type + ':' + al.severity : null;
if (fingerprint !== st.alert) {
    st.alert = fingerprint;
    if (al) out.push({ topic: base + 'alert', payload: Object.assign({ ts }, al) });
}

flow.set(key, st);
return [out];
